import sys, os, time; sys.path.insert(0, os.getcwd())
import numpy as np, gen
from scipy.optimize import minimize
from scipy.ndimage import gaussian_filter, shift as nshift
t0=time.time()
mA,fA=gen.load('A');mB,fB=gen.load('B')
d=np.load('syn.npz');X,y=d['X'],d['y']
Xa,_=gen.make(3000,11); print('gen',time.time()-t0)
rng=np.random.default_rng(3)
def aug(X):
    out=[]
    for x in X:
        im=x.reshape(8,8)
        if rng.random()<.5: im=gaussian_filter(im,rng.uniform(.3,.7))
        if rng.random()<.4: im=nshift(im,(rng.integers(-1,2),rng.integers(-1,2)),order=0)
        im=np.clip(im*rng.uniform(.7,1.4)+rng.normal(0,rng.uniform(0,.1),im.shape),0,1)
        out.append(im.ravel())
    return np.array(out)
Xtr=np.vstack([X,Xa,aug(X),aug(Xa),np.clip(.5*X+.5*Xa,0,1)])
def h1A(x): return fA(x@mA['W0']+mA['b0'])
def Bfrom(z):
    h1=fB(z); h2=fB(h1@mB['W1']+mB['b1']); return h2@mB['W2']+mB['b2']
Xte,yte=gen.make(1000,7)
tests={'clean':Xte,'aug':aug(Xte),'blur':np.array([gaussian_filter(x.reshape(8,8),.6).ravel() for x in Xte]),
       'noise':np.clip(Xte+rng.normal(0,.15,Xte.shape),0,1)}
def ev(M,c):
    r={}
    for k,T in tests.items():
        r[k]=round((Bfrom(h1A(T)@M+c).argmax(1)==Bfrom(T@mB['W0']+mB['b0']).argmax(1)).mean(),3)
    return r
old=np.load('bridge.npz'); print('old',ev(old['M'],old['c']))
HA=h1A(Xtr); ZB=Xtr@mB['W0']+mB['b0']; N=len(Xtr); hA,hB=16,24
T=Bfrom(ZB); P=np.exp(T-T.max(1,keepdims=True)); P/=P.sum(1,keepdims=True)
def loss(th,lam=0.005):
    M=th[:hA*hB].reshape(hA,hB);c=th[hA*hB:]
    z=HA@M+c; h1=np.maximum(z,0); z2=h1@mB['W1']+mB['b1']; h2=np.maximum(z2,0); lg=h2@mB['W2']+mB['b2']
    q=lg-lg.max(1,keepdims=True); q=q-np.log(np.exp(q).sum(1,keepdims=True))
    R=z-ZB; L=-(P*q).sum()/N+lam*(R**2).sum()/N
    g=(np.exp(q)-P)/N; gh2=g@mB['W2'].T*(z2>0); gz=gh2@mB['W1'].T*(z>0)+2*lam*R/N
    return L,np.concatenate([(HA.T@gz).ravel(),gz.sum(0)])
r=minimize(loss,np.concatenate([old['M'].ravel(),old['c']]),jac=True,method='L-BFGS-B',options={'maxiter':2500})
M=r.x[:hA*hB].reshape(hA,hB);c=r.x[hA*hB:]
eo,en=ev(old['M'],old['c']),ev(M,c); print('new',en,r.nit,time.time()-t0)
if np.mean(list(en.values()))>np.mean(list(eo.values())):
    np.savez('bridge_v1.npz',M=old['M'],c=old['c']); np.savez('bridge.npz',M=M,c=c); print('saved new')
